codetemplate.code:
SELECT *
FROM ${table}
QUALIFY row_number() OVER (PARTITION BY ${key} ORDER BY ${order} DESC) <= ${n default="1"}${cursor};

SELECT ${dims}, ${agg default="count(*)"}
FROM ${table}
GROUP BY ALL
ORDER BY ALL${cursor};

SELECT ${l default="l"}.*, ${r default="r"}.${rcol}
FROM ${left} ${l}
ASOF JOIN ${right} ${r}
  ON ${l}.${key} = ${r}.${key} AND ${l}.${ts default="ts"} >= ${r}.${ts}${cursor};

WITH ${cte default="cte"} AS (
    ${query}
)
SELECT * FROM ${cte}${cursor};

INSERT INTO ${table} BY NAME
SELECT ${cols} FROM ${source}
ON CONFLICT DO UPDATE SET ${col} = excluded.${col}${cursor};

SELECT * FROM (VALUES
    (${v1 default="1"}, '${v2 default="a"}'),
    (2, 'b')
) AS ${alias default="t"}(${cols default="id, name"})${cursor};

SELECT date_trunc('${part default="month"}', ${ts}) AS bucket, ${agg default="count(*)"}
FROM ${table}
GROUP BY ALL ORDER BY ALL${cursor};
